-- Additive currentLive MonsterAA compatibility adapters after012.
-- Raw legacy cooldown targets are translated by explicit named ability/family
-- semantics; no native +5000 normalization is claimed. Exact seconds retained.
-- Existing311 paid ranks and all free roots remain unchanged. Imp5 untouched.
-- AttackSpeed uses reviewed shroud-only native Live composition; old RoF2
-- native haste display omits the AA contribution. Native gameplay test pending.
CREATE TEMPORARY TABLE shroud013_ability LIKE aa_ability;
CREATE TEMPORARY TABLE shroud013_rank LIKE aa_ranks;
CREATE TEMPORARY TABLE shroud013_effect LIKE aa_rank_effects;
CREATE TEMPORARY TABLE shroud013_prereq LIKE aa_rank_prereqs;
CREATE TEMPORARY TABLE shroud013_oldlink LIKE spirit_shroud_abilities;
CREATE TEMPORARY TABLE shroud013_link LIKE spirit_shroud_abilities;
CREATE TEMPORARY TABLE shroud013_old LIKE spirit_shroud_templates;
CREATE TEMPORARY TABLE shroud013_template LIKE spirit_shroud_templates;
CREATE TEMPORARY TABLE shroud013_protected_ability LIKE aa_ability;
CREATE TEMPORARY TABLE shroud013_protected_rank LIKE aa_ranks;
CREATE TEMPORARY TABLE shroud013_protected_effect LIKE aa_rank_effects;
CREATE TEMPORARY TABLE shroud013_protected_prereq LIKE aa_rank_prereqs;
CREATE TEMPORARY TABLE shroud013_guard(ok TINYINT NOT NULL CHECK(ok=1))ENGINE=InnoDB;
START TRANSACTION;
NOT EXISTS(SELECT 1 FROM spirit_shroud_state s JOIN shroud013_template t ON t.id=s.template_id)
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_sessions s JOIN shroud013_template t ON t.id=s.template_id WHERE s.phase='active')
 AND NOT EXISTS(SELECT 1 FROM character_alternate_abilities WHERE aa_id BETWEEN 49000 AND 49099)
 AND NOT EXISTS(SELECT 1 FROM shroud_original_character_alternate_abilities WHERE aa_id BETWEEN 49000 AND 49099)
 AND NOT EXISTS(SELECT 1 FROM shroud013_template n JOIN shroud013_old o ON o.id=n.id LEFT JOIN spirit_shroud_templates a ON a.id=n.id WHERE a.id IS NULL OR NOT((a.`id`<=>o.`id` AND a.`progression_id`<=>o.`progression_id` AND a.`branch_id`<=>o.`branch_id` AND a.`level`<=>o.`level` AND a.`race`<=>o.`race` AND a.`class_id`<=>o.`class_id` AND a.`gender`<=>o.`gender` AND a.`hp`<=>o.`hp` AND a.`mana`<=>o.`mana` AND a.`endurance`<=>o.`endurance` AND a.`base_stat`<=>o.`base_stat` AND a.`unlock_xp`<=>o.`unlock_xp` AND a.`name`<=>o.`name` AND a.`description`<=>o.`description` AND a.`progression_name`<=>o.`progression_name` AND a.`branch_name`<=>o.`branch_name` AND a.`enabled`<=>o.`enabled` AND a.`content_version`<=>o.`content_version` AND a.`verified`<=>o.`verified` AND a.`test_only`<=>o.`test_only` AND a.`evidence_ref`<=>o.`evidence_ref` AND a.`monster_points`<=>o.`monster_points` AND a.`stat_str`<=>o.`stat_str` AND a.`stat_sta`<=>o.`stat_sta` AND a.`stat_cha`<=>o.`stat_cha` AND a.`stat_dex`<=>o.`stat_dex` AND a.`stat_int`<=>o.`stat_int` AND a.`stat_agi`<=>o.`stat_agi` AND a.`stat_wis`<=>o.`stat_wis` AND a.`resource_maxima`<=>o.`resource_maxima` AND a.`model_size`<=>o.`model_size`)OR(a.`id`<=>n.`id` AND a.`progression_id`<=>n.`progression_id` AND a.`branch_id`<=>n.`branch_id` AND a.`level`<=>n.`level` AND a.`race`<=>n.`race` AND a.`class_id`<=>n.`class_id` AND a.`gender`<=>n.`gender` AND a.`hp`<=>n.`hp` AND a.`mana`<=>n.`mana` AND a.`endurance`<=>n.`endurance` AND a.`base_stat`<=>n.`base_stat` AND a.`unlock_xp`<=>n.`unlock_xp` AND a.`name`<=>n.`name` AND a.`description`<=>n.`description` AND a.`progression_name`<=>n.`progression_name` AND a.`branch_name`<=>n.`branch_name` AND a.`enabled`<=>n.`enabled` AND a.`content_version`<=>n.`content_version` AND a.`verified`<=>n.`verified` AND a.`test_only`<=>n.`test_only` AND a.`evidence_ref`<=>n.`evidence_ref` AND a.`monster_points`<=>n.`monster_points` AND a.`stat_str`<=>n.`stat_str` AND a.`stat_sta`<=>n.`stat_sta` AND a.`stat_cha`<=>n.`stat_cha` AND a.`stat_dex`<=>n.`stat_dex` AND a.`stat_int`<=>n.`stat_int` AND a.`stat_agi`<=>n.`stat_agi` AND a.`stat_wis`<=>n.`stat_wis` AND a.`resource_maxima`<=>n.`resource_maxima` AND a.`model_size`<=>n.`model_size`)))
 AND NOT EXISTS(SELECT 1 FROM aa_ability a JOIN shroud013_ability e ON a.id=e.id WHERE NOT(a.`id`<=>e.`id` AND a.`name`<=>e.`name` AND a.`category`<=>e.`category` AND a.`classes`<=>e.`classes` AND a.`type`<=>e.`type` AND a.`grant_only`<=>e.`grant_only` AND a.`first_rank_id`<=>e.`first_rank_id` AND a.`charges`<=>e.`charges` AND a.`enabled`<=>e.`enabled` AND a.`status`<=>e.`status` AND a.`races`<=>e.`races` AND a.`deities`<=>e.`deities` AND a.`drakkin_heritage`<=>e.`drakkin_heritage` AND a.`reset_on_death`<=>e.`reset_on_death` AND a.`auto_grant_enabled`<=>e.`auto_grant_enabled`))
 AND NOT EXISTS(SELECT 1 FROM aa_ability a LEFT JOIN shroud013_ability e ON a.id=e.id WHERE a.id BETWEEN 49000 AND 49099 AND e.id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM aa_ranks a JOIN shroud013_rank e ON a.id=e.id WHERE NOT(a.`id`<=>e.`id` AND a.`upper_hotkey_sid`<=>e.`upper_hotkey_sid` AND a.`lower_hotkey_sid`<=>e.`lower_hotkey_sid` AND a.`title_sid`<=>e.`title_sid` AND a.`desc_sid`<=>e.`desc_sid` AND a.`cost`<=>e.`cost` AND a.`level_req`<=>e.`level_req` AND a.`spell`<=>e.`spell` AND a.`spell_type`<=>e.`spell_type` AND a.`recast_time`<=>e.`recast_time` AND a.`prev_id`<=>e.`prev_id` AND a.`next_id`<=>e.`next_id` AND a.`expansion`<=>e.`expansion`))
 AND NOT EXISTS(SELECT 1 FROM aa_ranks a LEFT JOIN shroud013_rank e ON a.id=e.id WHERE a.id BETWEEN 49000 AND 49099 AND e.id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM aa_rank_effects a JOIN shroud013_effect e ON a.rank_id=e.rank_id AND a.slot=e.slot WHERE NOT(a.`rank_id`<=>e.`rank_id` AND a.`slot`<=>e.`slot` AND a.`effect_id`<=>e.`effect_id` AND a.`base1`<=>e.`base1` AND a.`base2`<=>e.`base2`))
 AND NOT EXISTS(SELECT 1 FROM aa_rank_effects a LEFT JOIN shroud013_effect e ON a.rank_id=e.rank_id AND a.slot=e.slot WHERE a.rank_id BETWEEN 49000 AND 49099 AND e.rank_id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM aa_rank_prereqs a JOIN shroud013_prereq e ON a.rank_id=e.rank_id AND a.aa_id=e.aa_id WHERE NOT(a.`rank_id`<=>e.`rank_id` AND a.`aa_id`<=>e.`aa_id` AND a.`points`<=>e.`points`))
 AND NOT EXISTS(SELECT 1 FROM aa_rank_prereqs a LEFT JOIN shroud013_prereq e ON a.rank_id=e.rank_id AND a.aa_id=e.aa_id WHERE a.rank_id BETWEEN 49000 AND 49099 AND e.rank_id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM aa_ability a LEFT JOIN shroud013_ability e ON e.id=a.id WHERE a.first_rank_id BETWEEN 49000 AND 49099 AND e.id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM aa_ranks a LEFT JOIN shroud013_rank e ON e.id=a.id WHERE (a.prev_id BETWEEN 49000 AND 49099 OR a.next_id BETWEEN 49000 AND 49099) AND e.id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM aa_rank_prereqs a LEFT JOIN shroud013_prereq e ON e.rank_id=a.rank_id AND e.aa_id=a.aa_id WHERE a.aa_id BETWEEN 49000 AND 49099 AND e.rank_id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_abilities a LEFT JOIN shroud013_link e ON e.template_id=a.template_id AND e.rank_id=a.rank_id WHERE a.rank_id BETWEEN 49000 AND 49099 AND e.rank_id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM shroud013_protected_ability e LEFT JOIN aa_ability a ON a.id=e.id WHERE a.id IS NULL OR NOT(a.`id`<=>e.`id` AND a.`name`<=>e.`name` AND a.`category`<=>e.`category` AND a.`classes`<=>e.`classes` AND a.`type`<=>e.`type` AND a.`grant_only`<=>e.`grant_only` AND a.`first_rank_id`<=>e.`first_rank_id` AND a.`charges`<=>e.`charges` AND a.`enabled`<=>e.`enabled` AND a.`status`<=>e.`status` AND a.`races`<=>e.`races` AND a.`deities`<=>e.`deities` AND a.`drakkin_heritage`<=>e.`drakkin_heritage` AND a.`reset_on_death`<=>e.`reset_on_death` AND a.`auto_grant_enabled`<=>e.`auto_grant_enabled`))
 AND NOT EXISTS(SELECT 1 FROM aa_ability a LEFT JOIN shroud013_protected_ability e ON a.id=e.id WHERE a.id BETWEEN 48400 AND 48710 AND e.id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM shroud013_protected_rank e LEFT JOIN aa_ranks a ON a.id=e.id WHERE a.id IS NULL OR NOT(a.`id`<=>e.`id` AND a.`upper_hotkey_sid`<=>e.`upper_hotkey_sid` AND a.`lower_hotkey_sid`<=>e.`lower_hotkey_sid` AND a.`title_sid`<=>e.`title_sid` AND a.`desc_sid`<=>e.`desc_sid` AND a.`cost`<=>e.`cost` AND a.`level_req`<=>e.`level_req` AND a.`spell`<=>e.`spell` AND a.`spell_type`<=>e.`spell_type` AND a.`recast_time`<=>e.`recast_time` AND a.`prev_id`<=>e.`prev_id` AND a.`next_id`<=>e.`next_id` AND a.`expansion`<=>e.`expansion`))
 AND NOT EXISTS(SELECT 1 FROM aa_ranks a LEFT JOIN shroud013_protected_rank e ON a.id=e.id WHERE a.id BETWEEN 48400 AND 48710 AND e.id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM shroud013_protected_effect e LEFT JOIN aa_rank_effects a ON a.rank_id=e.rank_id AND a.slot=e.slot WHERE a.rank_id IS NULL OR NOT(a.`rank_id`<=>e.`rank_id` AND a.`slot`<=>e.`slot` AND a.`effect_id`<=>e.`effect_id` AND a.`base1`<=>e.`base1` AND a.`base2`<=>e.`base2`))
 AND NOT EXISTS(SELECT 1 FROM aa_rank_effects a LEFT JOIN shroud013_protected_effect e ON a.rank_id=e.rank_id AND a.slot=e.slot WHERE a.rank_id BETWEEN 48400 AND 48710 AND e.rank_id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM shroud013_protected_prereq e LEFT JOIN aa_rank_prereqs a ON a.rank_id=e.rank_id AND a.aa_id=e.aa_id WHERE a.rank_id IS NULL OR NOT(a.`rank_id`<=>e.`rank_id` AND a.`aa_id`<=>e.`aa_id` AND a.`points`<=>e.`points`))
 AND NOT EXISTS(SELECT 1 FROM aa_rank_prereqs a LEFT JOIN shroud013_protected_prereq e ON a.rank_id=e.rank_id AND a.aa_id=e.aa_id WHERE a.rank_id BETWEEN 48400 AND 48710 AND e.rank_id IS NULL)
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_templates t JOIN shroud013_old v ON v.id=t.id JOIN spirit_shroud_abilities a ON a.template_id=t.id AND a.free_grant=0 LEFT JOIN shroud013_oldlink e ON e.template_id=a.template_id AND e.rank_id=a.rank_id WHERE t.content_version=v.content_version AND(e.template_id IS NULL OR NOT(a.`template_id`<=>e.`template_id` AND a.`rank_id`<=>e.`rank_id` AND a.`free_grant`<=>e.`free_grant` AND a.`display_rank`<=>e.`display_rank` AND a.`display_max_rank`<=>e.`display_max_rank` AND a.`display_total_cost`<=>e.`display_total_cost`)))
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_templates t JOIN shroud013_old v ON v.id=t.id JOIN shroud013_oldlink e ON e.template_id=t.id LEFT JOIN spirit_shroud_abilities a ON a.template_id=e.template_id AND a.rank_id=e.rank_id WHERE t.content_version=v.content_version AND(a.template_id IS NULL OR NOT(a.`template_id`<=>e.`template_id` AND a.`rank_id`<=>e.`rank_id` AND a.`free_grant`<=>e.`free_grant` AND a.`display_rank`<=>e.`display_rank` AND a.`display_max_rank`<=>e.`display_max_rank` AND a.`display_total_cost`<=>e.`display_total_cost`)))
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_templates t JOIN shroud013_template v ON v.id=t.id JOIN spirit_shroud_abilities a ON a.template_id=t.id AND a.free_grant=0 LEFT JOIN shroud013_link e ON e.template_id=a.template_id AND e.rank_id=a.rank_id WHERE t.content_version=v.content_version AND(e.template_id IS NULL OR NOT(a.`template_id`<=>e.`template_id` AND a.`rank_id`<=>e.`rank_id` AND a.`free_grant`<=>e.`free_grant` AND a.`display_rank`<=>e.`display_rank` AND a.`display_max_rank`<=>e.`display_max_rank` AND a.`display_total_cost`<=>e.`display_total_cost`)))
 AND NOT EXISTS(SELECT 1 FROM spirit_shroud_templates t JOIN shroud013_template v ON v.id=t.id JOIN shroud013_link e ON e.template_id=t.id LEFT JOIN spirit_shroud_abilities a ON a.template_id=e.template_id AND a.rank_id=e.rank_id WHERE t.content_version=v.content_version AND(a.template_id IS NULL OR NOT(a.`template_id`<=>e.`template_id` AND a.`rank_id`<=>e.`rank_id` AND a.`free_grant`<=>e.`free_grant` AND a.`display_rank`<=>e.`display_rank` AND a.`display_max_rank`<=>e.`display_max_rank` AND a.`display_total_cost`<=>e.`display_total_cost`)))
 AND NOT EXISTS(SELECT 1 FROM shroud013_link x LEFT JOIN spirit_shroud_abilities p ON p.template_id=x.template_id AND p.rank_id=48117 LEFT JOIN aa_ability b ON b.id=48117 WHERE x.rank_id BETWEEN 49013 AND 49017 AND(p.rank_id IS NULL OR p.free_grant<>1 OR p.display_rank<>1 OR p.display_max_rank<>1 OR b.grant_only<>1))
