 AND EXISTS(SELECT 1 FROM aa_ability a JOIN aa_ranks r ON r.id=a.first_rank_id WHERE a.id=48132 AND a.name='Plane Shift: Material' AND a.first_rank_id=48132 AND a.grant_only=1 AND r.spell=7542 AND r.level_req=60 AND r.cost=0 AND r.prev_id=-1 AND r.next_id=-1)
 AND EXISTS(SELECT 1 FROM aa_ability a JOIN aa_ranks r ON r.id=a.first_rank_id WHERE a.id=48133 AND a.name='Plane Shift: Blink' AND a.first_rank_id=48133 AND a.grant_only=1 AND r.spell=7543 AND r.level_req=70 AND r.cost=0 AND r.prev_id=-1 AND r.next_id=-1),1,0);
UPDATE spirit_shroud_templates a JOIN shroud013_template t ON t.id=a.id SET a.content_version=t.content_version;
DELETE g FROM spirit_shroud_content_gaps g JOIN shroud013_template t ON t.id=g.template_id WHERE g.field_name IN('paid:Attack Speed','paid:Enduring Voice','paid:Improved Plane Shift');
COMMIT;
