INSERT INTO shroud013_guard SELECT IF(
INSERT INTO aa_ability SELECT * FROM shroud013_ability ON DUPLICATE KEY UPDATE `id`=VALUES(`id`);
INSERT INTO aa_ranks SELECT * FROM shroud013_rank ON DUPLICATE KEY UPDATE `id`=VALUES(`id`);
INSERT INTO aa_rank_effects SELECT * FROM shroud013_effect ON DUPLICATE KEY UPDATE `rank_id`=VALUES(`rank_id`);
INSERT INTO aa_rank_prereqs SELECT * FROM shroud013_prereq ON DUPLICATE KEY UPDATE `rank_id`=VALUES(`rank_id`);
INSERT INTO spirit_shroud_abilities SELECT a.* FROM shroud013_link a WHERE a.rank_id BETWEEN 49000 AND 49099 ON DUPLICATE KEY UPDATE rank_id=VALUES(rank_id);
